$$\begin{array}{l}
  {\nabla T = \frac{\partial T}{\partial x}\mathbf{i} + \frac{\partial T}{\partial y}\mathbf{j} + \frac{\partial T}{\partial z}\mathbf{k}} \\
  {\phantom{\nabla T}{= - \frac{160x}{{({1 + x^{2} + 2y^{2} + 3z^{2}})}^{2}}\mathbf{i} - \frac{320y}{{({1 + x^{2} + 2y^{2} + 3z^{2}})}^{2}}\mathbf{j} - \frac{480z}{{({1 + x^{2} + 2y^{2} + 3z^{2}})}^{2}}\mathbf{k}}} \\
  {\phantom{\nabla T}{= \frac{160}{{({1 + x^{2} + 2y^{2} + 3z^{2}})}^{2}}{({- x\mathbf{i} - 2y\mathbf{j} - 3z\mathbf{k}})}}}
  \end{array}$$
